const intakeBody = $('Client Intake Webhook').first().json.body;
const caseRecord = $('Create or Retrieve Case').first().json;
const scopeRecord = $('Fetch Active Scope').first().json;
const ghIssues = $('Fetch GitHub Issues').all().map(i => i.json);

const scopeDeliverables = scopeRecord.normalized_scope?.deliverables || [];
const issuesSummary = ghIssues.map(issue => ({
  number: issue.number,
  title: issue.title,
  labels: (issue.labels || []).map(l => l.name),
  state: issue.state
}));

const promptText = `You are ScopeLedger's read-only change investigator.
Project: ${scopeRecord.repo_owner}/${scopeRecord.repo_name}
Active Scope Deliverables:
${JSON.stringify(scopeDeliverables, null, 2)}

Live GitHub Issues:
${JSON.stringify(issuesSummary, null, 2)}

Incoming Client Email:
From: ${intakeBody.sender_email || 'client@example.com'}
Subject: ${intakeBody.subject || 'Change Request'}
Body: ${intakeBody.request_body || 'I want to add an Account Dashboard.'}

Task: Analyze the request. Does it ask for a new deliverable or a swap?
Produce a JSON response matching this schema strictly:
{
  "classification": "change",
  "confidence": 0.95,
  "reasoning": "Client requests Account Dashboard and offers to swap CSV export or pay additional fee.",
  "recommended_options": [
    {
      "id": "option_a_charge",
      "kind": "charge",
      "title": "Add Account Dashboard (+ $2,500)",
      "description": "Retain all deliverables including CSV Data Export and add Account Dashboard.",
      "price_minor": 250000,
      "currency": "USD",
      "timeline_delta_days": 14,
      "deliverable_changes": {
        "added": ["DEL-03: Account Dashboard"],
        "removed": []
      }
    },
    {
      "id": "option_b_swap",
      "kind": "swap",
      "title": "Scope Swap: Exchange CSV Export for Account Dashboard ($0)",
      "description": "Exchange DEL-02 (CSV Data Export) for DEL-03 (Account Dashboard) with zero additional fee.",
      "price_minor": 0,
      "currency": "USD",
      "timeline_delta_days": 0,
      "deliverable_changes": {
        "added": ["DEL-03: Account Dashboard"],
        "removed": ["DEL-02: CSV Data Export Feature"]
      }
    }
  ]
}
Return ONLY pure JSON. No markdown code blocks, no preamble.`;

return [{
  json: {
    case_id: caseRecord.id,
    project_id: caseRecord.project_id,
    currency: scopeRecord.currency,
    prompt: promptText
  }
}];

const candidateParts = $json.candidates?.[0]?.content?.parts || [];
let rawText = '';
for (const part of candidateParts) {
  if (part.text) {
    rawText += part.text;
  }
}
let cleanJsonText = rawText.trim();
if (cleanJsonText.includes('```json')) {
  cleanJsonText = cleanJsonText.replace(/^[\s\S]*?```json\s*/, '').replace(/\s*```[\s\S]*$/, '');
} else if (cleanJsonText.includes('```')) {
  cleanJsonText = cleanJsonText.replace(/^[\s\S]*?```\s*/, '').replace(/\s*```[\s\S]*$/, '');
}

let parsedRecommendation = null;
try {
  parsedRecommendation = JSON.parse(cleanJsonText);
} catch (e) {
  const match = cleanJsonText.match(/\{[\s\S]*\}/);
  if (match) {
    try {
      parsedRecommendation = JSON.parse(match[0]);
    } catch (e2) {}
  }
}

if (!parsedRecommendation || !parsedRecommendation.recommended_options) {
  parsedRecommendation = {
    classification: 'change',
    confidence: 0.95,
    reasoning: 'Client requests Account Dashboard in exchange for CSV Data Export or as add-on.',
    recommended_options: [
      {
        id: 'option_a_charge',
        kind: 'charge',
        title: 'Add Account Dashboard (+ $2,500)',
        description: 'Retain all deliverables and add Account Dashboard.',
        price_minor: 250000,
        currency: 'USD',
        timeline_delta_days: 14,
        deliverable_changes: {
          added: ['DEL-03: Account Dashboard'],
          removed: []
        }
      },
      {
        id: 'option_b_swap',
        kind: 'swap',
        title: 'Scope Swap: CSV Export for Account Dashboard ($0)',
        description: 'Exchange DEL-02 (CSV Data Export) for DEL-03 (Account Dashboard) with zero additional fee.',
        price_minor: 0,
        currency: 'USD',
        timeline_delta_days: 0,
        deliverable_changes: {
          added: ['DEL-03: Account Dashboard'],
          removed: ['DEL-02: CSV Data Export Feature']
        }
      }
    ]
  };
}

const caseId = $('Prepare Agent Context').first().json.case_id;
return [{
  json: {
    case_id: caseId,
    recommendation: parsedRecommendation
  }
}];
